try:
    from enum import StrEnum
except ImportError:
    from enum import Enum
    class StrEnum(str, Enum):
        pass


class MemoryDomain(StrEnum): SESSION = "SESSION"; PERSONAL = "PERSONAL"; OPERATIONAL = "OPERATIONAL"
class Sensitivity(StrEnum): ORDINARY = "ORDINARY"; PERSONAL = "PERSONAL"; SENSITIVE = "SENSITIVE"; PROHIBITED = "PROHIBITED"
class SemanticType(StrEnum): DECISION = "DECISION"; CONSTRAINT = "CONSTRAINT"; PREFERENCE = "PREFERENCE"; PERSONAL_STATE = "PERSONAL_STATE"; PERSONAL_FACT = "PERSONAL_FACT"; HEALTH_CLAIM = "HEALTH_CLAIM"; EXPERIENCE = "EXPERIENCE"; RELATIONSHIP = "RELATIONSHIP"; CREDENTIAL = "CREDENTIAL"; TEMPORARY_EVENT = "TEMPORARY_EVENT"; OTHER = "OTHER"
class TemporalScope(StrEnum): INSTANT = "INSTANT"; SESSION = "SESSION"; TEMPORARY = "TEMPORARY"; DURABLE = "DURABLE"; UNKNOWN = "UNKNOWN"
class PersistenceIntent(StrEnum): NONE = "NONE"; IMPLICIT = "IMPLICIT"; EXPLICIT = "EXPLICIT"; EXPLICIT_TEMPORARY = "EXPLICIT_TEMPORARY"; FORGET_REQUEST = "FORGET_REQUEST"
