class PayloadStatus(StrEnum): STAGED = "STAGED"; ACTIVE = "ACTIVE"; PURGE_PENDING = "PURGE_PENDING"; DESTROYED = "DESTROYED"; ABORTED = "ABORTED"
class RecordStatus(StrEnum): ACTIVE = "ACTIVE"; SUPERSEDED = "SUPERSEDED"; RETRACTED = "RETRACTED"; PURGE_REVOKED = "PURGE_REVOKED"; PURGED = "PURGED"
class Lifetime(StrEnum): SESSION = "SESSION"; TEMPORARY = "TEMPORARY"; DURABLE = "DURABLE"
class PatchOperationType(StrEnum): ADD = "ADD"; SUPERSEDE = "SUPERSEDE"; RETRACT = "RETRACT"; LINK = "LINK"; FLAG_CONFLICT = "FLAG_CONFLICT"; RESOLVE_CONFLICT = "RESOLVE_CONFLICT"; PURGE_REQUEST = "PURGE_REQUEST"
